using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using Comfort.Common;
using EFT;
using EFT.InventoryLogic;
using UnityEngine;
namespace LocalSpt5Esp;
internal static class AiBackpackEditor {
 sealed record Row(Item Item,string Path,string Name);
 static readonly List<Row> rows=new();static readonly List<(string Id,string Name)> templates=new();
 static Player? target;static IntPtr worldPointer,targetPointer,backpackPointer;static string profile="",name="",notice="",query="",cachedQuery="\0",quantity="1",stack="1";static bool adding,changeStack;
 static Item? selected;static ItemComponentEditor? editor;static Vector2 listScroll,editScroll;static float nextRefresh;
 internal static bool Open=>target!=null;
 internal static void Close(){target=null;selected=null;editor=null;rows.Clear();templates.Clear();cachedQuery="\0";worldPointer=targetPointer=backpackPointer=IntPtr.Zero;profile="";}
 internal static void Select(GameWorld world,Player player){Close();worldPointer=world.Pointer;target=player;targetPointer=player.Pointer;profile=player.ProfileId;name=player.Profile?.Nickname??profile;notice="只修改当前 AI 的背包内容；AI 可能在行动中使用或移动这些物品。";adding=false;listScroll=editScroll=Vector2.zero;nextRefresh=0;}
 static CompoundItem Backpack(){var world=Singleton<GameWorld>.Instance;if(!RaidClock.Active||world?.Pointer!=worldPointer||target==null||target.Pointer!=targetPointer||target.ProfileId!=profile||target.IsYourPlayer||!target.IsAI||target.HealthController?.IsAlive!=true)throw new ArgumentException("该 AI 或原战局已不可用，请返回列表重新选择。");bool present=false;var alive=world.AllAlivePlayersList;if(alive!=null)for(int i=0;i<alive.Count;i++)if(alive[i]?.Pointer==targetPointer){present=true;break;}if(!present)throw new ArgumentException("该 AI 已不在当前战局。");return target.Profile?.Inventory?.Equipment?.GetSlot(EquipmentSlot.Backpack)?.ContainedItem?.TryCast<CompoundItem>()??throw new ArgumentException("该 AI 没有带储物格的背包。");}
 static void Refresh(){var bag=Backpack();if(backpackPointer!=IntPtr.Zero&&backpackPointer!=bag.Pointer){selected=null;editor=null;notice="AI 更换了背包，已清除之前的物品选择。";}backpackPointer=bag.Pointer;rows.Clear();var seen=new HashSet<IntPtr>();void Visit(Item item,string path,int depth){if(depth>12||!seen.Add(item.Pointer))return;string title=LootDisplay.ItemName(item,false);rows.Add(new(item,path,title));var compound=item.TryCast<CompoundItem>();if(compound?.Grids!=null)foreach(var grid in compound.Grids)if(grid!=null)foreach(var child in grid.Items)if(child!=null)Visit(child,path+" / "+title,depth+1);if(compound?.Slots!=null)foreach(var slot in compound.Slots)if(slot?.ContainedItem is Item child)Visit(child,path+" / "+title,depth+1);var weapon=item.TryCast<Weapon>();if(weapon?.Chambers!=null)foreach(var chamber in weapon.Chambers)if(chamber?.ContainedItem is Item child)Visit(child,path+" / "+title,depth+1);}
  if(bag.Grids!=null)foreach(var grid in bag.Grids)if(grid!=null)foreach(var item in grid.Items)if(item!=null)Visit(item,"背包",0);nextRefresh=Time.unscaledTime+1;if(selected!=null&&!rows.Any(r=>r.Item.Pointer==selected.Pointer)){selected=null;editor=null;notice="所选物品已被 AI 移走或使用，请重新选择。";}}
 static Item RequireSelected(){var pointer=selected?.Pointer??IntPtr.Zero;Refresh();return rows.FirstOrDefault(r=>r.Item.Pointer==pointer)?.Item??throw new ArgumentException("物品已离开该 AI 的背包，请刷新列表。");}
 static void Choose(Item item){selected=item;editor=new(item,new ItemComponentParameters());stack=item.StackObjectsCount.ToString(CultureInfo.InvariantCulture);changeStack=false;editScroll=Vector2.zero;}
 static void Edit(){var item=RequireSelected();var bag=Backpack();var requested=editor?.Read()??new();int count=changeStack?ItemSpawnRules.Integer(stack,1,Math.Max(1,item.StackMaxSize),"堆叠数量"):item.StackObjectsCount;var original=LoadoutPlans.Parameters(item);int originalCount=item.StackObjectsCount;var factory=Singleton<ItemFactory>.Instance??throw new ArgumentException("物品工厂尚未就绪。");var preview=factory.CreateItem(factory.NextId.ToString(),item.StringTemplateId,null);original.Apply(preview);requested.Apply(preview);
  try{requested.Apply(item);if(changeStack)item.StackObjectsCount=count;item.RaiseRefreshEvent(true,true);bag.RaiseRefreshEvent(true,true);var actual=LoadoutPlans.Parameters(item).Attributes();var differences=requested.Attributes().Where(pair=>!actual.TryGetValue(pair.Key,out var value)||!Equals(value,pair.Value)).Select(pair=>pair.Key+"：请求 "+pair.Value+"，回读 "+actual.GetValueOrDefault(pair.Key)).ToArray();notice=differences.Length==0?"物品参数已写入并回读一致。":"游戏调整了部分参数："+string.Join("；",differences);FeatureToasts.Show("AI 背包物品参数已更新");Choose(item);}catch{original.Apply(item);item.StackObjectsCount=originalCount;item.RaiseRefreshEvent(true,true);throw;}}
 static void Delete(){var item=RequireSelected();var bag=Backpack();var controller=target!.InventoryController??throw new ArgumentException("AI 库存控制器尚未就绪。");string title=LootDisplay.ItemName(item,false);var result=ItemManipulator.Remove(item,controller,false);if(!result.Succeeded)throw new ArgumentException("游戏拒绝移除该物品，可能是必需附件或物品正被使用。");result.Value.RaiseEvents(controller.Cast<IItemOwner>(),CommandStatus.Succeed);bag.RaiseRefreshEvent(true,true);Refresh();if(rows.Any(r=>r.Item.Pointer==item.Pointer))throw new InvalidOperationException("移除后物品仍在背包，请重新检查。");selected=null;editor=null;notice="已删除："+title+"（含它内部的物品）。";FeatureToasts.Show("AI 背包物品已删除");}
 static void Add(string template){var bag=Backpack();var controller=target!.InventoryController??throw new ArgumentException("AI 库存控制器尚未就绪。");var factory=Singleton<ItemFactory>.Instance??throw new ArgumentException("物品工厂尚未就绪。");int wanted=ItemSpawnRules.Integer(quantity,1,int.MaxValue,"数量"),added=0;while(added<wanted){var item=factory.CreateItem(factory.NextId.ToString(),template,null);item.StackObjectsCount=Math.Min(wanted-added,Math.Max(1,item.StackMaxSize));ItemAddress? destination=null;if(bag.Grids!=null)foreach(var grid in bag.Grids){var candidate=grid?.FindLocationForItem(item);if(candidate!=null&&ItemManipulator.Add(item,candidate,controller,true).Succeeded){destination=candidate;break;}}if(destination==null)break;controller.AddAndRaiseEvents(item,destination);if(item.CurrentAddress==null)break;added=checked(added+item.StackObjectsCount);}bag.RaiseRefreshEvent(true,true);Refresh();notice=$"已添加 {added}/{wanted}；实际数量取决于该 AI 背包空间与物品限制。";if(added>0)FeatureToasts.Show("已向 AI 背包添加物品 ×"+added);}
 static void Action(Action action){try{action();}catch(Exception e){notice=e.Message;Plugin.Self.Log.LogWarning("AI backpack: "+e.Message);}}
 internal static void Draw(Rect rect){if(Time.unscaledTime>=nextRefresh){nextRefresh=Time.unscaledTime+1;Action(Refresh);}float x=rect.x,y=rect.y,w=rect.width;if(InterfaceMenu.Button(new Rect(x,y,116,30),"返回 AI 列表")){Close();return;}InterfaceMenu.Label(new Rect(x+130,y,w-270,30),"AI 背包 · "+name,InterfaceMenu.Accent,17);if(InterfaceMenu.Button(new Rect(x+w-124,y,124,30),"刷新背包"))Action(Refresh);y+=42;
  if(InterfaceMenu.Button(new Rect(x,y,150,30),"当前背包物品",!adding)){adding=false;listScroll=Vector2.zero;}if(InterfaceMenu.Button(new Rect(x+158,y,150,30),"添加物品",adding)){adding=true;listScroll=Vector2.zero;}y+=42;var body=new Rect(x,y,w,Math.Max(70,rect.yMax-y-66));
  if(adding){InterfaceMenu.Label(new Rect(x,y,38,30),"搜索",null,12);query=InterfaceMenu.Field(new Rect(x+42,y,Math.Max(80,w-230),30),query);InterfaceMenu.Label(new Rect(x+w-174,y,40,30),"数量",null,12);quantity=InterfaceMenu.Field(new Rect(x+w-128,y,128,30),quantity);if(cachedQuery!=query){cachedQuery=query;templates.Clear();templates.AddRange(ItemSpawner.FindTemplates(query));listScroll=Vector2.zero;}var area=new Rect(x,y+42,w,Math.Max(30,body.height-42));listScroll=GUI.BeginScrollView(area,listScroll,new Rect(0,0,w-20,templates.Count*44));int first=Math.Max(0,(int)(listScroll.y/44)),end=Math.Min(templates.Count,first+(int)Math.Ceiling(area.height/44)+2);string? add=null;for(int i=first;i<end;i++){var row=templates[i];InterfaceMenu.Label(new Rect(8,i*44,w-160,35),row.Name,null,12);if(InterfaceMenu.Button(new Rect(w-138,i*44,110,32),"添加到 AI"))add=row.Id;}GUI.EndScrollView();if(add!=null)Action(()=>Add(add));}
  else{float left=w*.53f;var area=new Rect(x,y,left,body.height);listScroll=GUI.BeginScrollView(area,listScroll,new Rect(0,0,left-20,Math.Max(50,rows.Count*68)));int first=Math.Max(0,(int)(listScroll.y/68)),end=Math.Min(rows.Count,first+(int)Math.Ceiling(body.height/68)+2);for(int i=first;i<end;i++){var row=rows[i];if(InterfaceMenu.WrappedButton(new Rect(0,i*68,left-26,61),row.Name+" ×"+row.Item.StackObjectsCount+"\n"+row.Path,selected?.Pointer==row.Item.Pointer))Action(()=>Choose(row.Item));}GUI.EndScrollView();var edit=new Rect(x+left+14,y,w-left-14,Math.Max(40,body.height-86));if(selected!=null&&editor!=null){editScroll=GUI.BeginScrollView(edit,editScroll,new Rect(0,0,edit.width-20,editor.Height+88));if(InterfaceMenu.Button(new Rect(0,0,edit.width-24,30),"修改堆叠数量 · "+(changeStack?"开启":"默认"),changeStack))changeStack=!changeStack;if(changeStack)stack=InterfaceMenu.Field(new Rect(0,36,edit.width-24,30),stack);editor.Draw(edit.width-24,82);GUI.EndScrollView();float buttonY=body.yMax-72;if(InterfaceMenu.Button(new Rect(edit.x,buttonY,edit.width,30),"应用参数并回读"))Action(Edit);if(InterfaceMenu.Button(new Rect(edit.x,buttonY+38,edit.width,30),"删除所选物品（含内部物品）"))Action(Delete);}else InterfaceMenu.Paragraph(edit,rows.Count==0?"该 AI 没有背包或背包为空；可添加物品后刷新。":"选择物品后编辑参数或删除。",null,13);}
  InterfaceMenu.Paragraph(new Rect(x,rect.yMax-58,w,54),notice,InterfaceMenu.Accent,12);
 }
}
